    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1080, height: 1527, deviceScaleFactor: 2 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle0' });

