const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1080, height: 1527, deviceScaleFactor: 2 });

  // Intercept and speed up the animation
  await page.evaluateOnNewDocument(() => {
    window.Math.random = () => 1; // Not related, just in case
    performance.now = () => Date.now() * 10; // Speed up time for the counter loop! Or just inject CSS
  });

  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle0' });

  // Hide menu
  await page.evaluate(() => {
    const menu = document.querySelector('.viz-menu');
    if (menu) menu.style.display = 'none';

    // Force set all counters to final values immediately
    document.querySelectorAll('[data-count]').forEach(el => {
      const target = parseFloat(el.dataset.count);
      const suffix = el.dataset.suffix || '';
      el.textContent = target + suffix;
    });
  });

  // Wait a bit for charts
  await new Promise(r => setTimeout(r, 1500));

  await page.screenshot({ path: '/app/output/final_poster.png', fullPage: true });
  await browser.close();
  console.log("Screenshot generated at /app/output/final_poster.png");
})();
